package escuela.sitioweb;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
class SitioDisenadorTest {
    SitioDiseno original() throws Exception {try(var input=getClass().getResourceAsStream("/sitioweb/disenador-original.json")){return tools.jackson.databind.json.JsonMapper.builder().build().readValue(input,SitioDiseno.class);}}
    SitioForm form(SitioDiseno d){var f=new SitioForm();f.setNombre("Escuela de prueba");f.setEslogan("Aprender juntos");f.setDiseno(d);return f;}
    SitioDiseno sencillo(){var d=new SitioDiseno();var b=new SitioDiseno.Bloque();b.setId("seccion-prueba");b.setTipo("seccion");b.setTitulo("Prueba");var c=new SitioComponente();c.setId("componente-prueba");c.setTexto("Texto seguro");b.getComponentes().add(c);d.getBloques().add(b);return d;}
    @Test void paginaOriginalCompletaSeValidaYRenderizaSinPerderTitulosLogoNiMenus()throws Exception {var d=original();try(var factory=jakarta.validation.Validation.buildDefaultValidatorFactory()){assertThat(factory.getValidator().validate(d)).isEmpty();}assertThatCode(()->d.validar(true)).doesNotThrowAnyException();assertThat(d.getBloques()).hasSize(9);var html=new SitioDisenadorRender().documento(form(d),"/imagenes/");assertThat(html).contains("Un mundo","explorar.","/images/logo.png","Oferta académica","Talleres","Inscripciones","Quiénes somos","site-footer","header-logo");}
    @Test void elRendererEscapaTextosYDestinosYSuprimeRamasOcultas(){var d=sencillo();var c=d.getTodosComponentes().getFirst();c.setTag("a");c.setTipo("enlace");c.setEnlace("https://example.org/?a=1&b=2");c.setTexto("<script>no ejecutar</script>");var html=new SitioDisenadorRender().documento(form(d),"/imagenes/");assertThat(html).contains("&lt;script&gt;","a=1&amp;b=2").doesNotContain("<script>");c.setVisible(false);assertThat(new SitioDisenadorRender().documento(form(d),"/imagenes/")).doesNotContain("no ejecutar");}
    @Test void recursosPublicosSeDerivanDelArbolYNoDeDatosEnviadosPorCliente(){var d=sencillo();var c=d.getTodosComponentes().getFirst();c.setTipo("contenedor");var image=new SitioComponente();image.setId("imagen-interna");image.setTipo("imagen");image.setTag("img");image.setImagenId(99L);image.setDescripcion("Prueba");c.getHijos().add(image);assertThat(d.getImagenesComponentes()).containsExactly(99L);c.setVisible(false);assertThat(d.getImagenesComponentes()).isEmpty();var mapper=tools.jackson.databind.json.JsonMapper.builder().build();String json=mapper.writeValueAsString(d);assertThat(mapper.readValue(json.replace("\"imagenesComponentes\":[]","\"imagenesComponentes\":[888]"),SitioDiseno.class).getImagenesComponentes()).isEmpty();}
    @Test void bloqueaIdentificadoresDuplicadosProfundidadYEnlacesEjecutables(){var d=sencillo();var c=d.getTodosComponentes().getFirst();c.getHijos().add(c);assertThatThrownBy(()->d.validar(false)).hasMessageContaining("identificador");c.getHijos().clear();c.setEnlace("javascript:alert(1)");assertThatThrownBy(()->d.validar(false)).hasMessageContaining("enlace");c.setEnlace("");var root=c;for(int i=0;i<14;i++){var child=new SitioComponente();child.setId("profundidad-"+i);root.getHijos().add(child);root=child;}assertThatThrownBy(()->d.validar(false)).hasMessageContaining("niveles");}
    @Test void estilosDeDispositivoSeValidanYSonIndependientes(){var d=sencillo();var n=d.getTodosComponentes().getFirst();var base=new SitioComponente.Estilo();base.setFuente(36);base.setX(40);n.getEstilos().put("escritorio",base);var mobile=new SitioComponente.Estilo();mobile.setFuente(16);n.getEstilos().put("movil",mobile);String html=new SitioDisenadorRender().documento(form(d),"/imagenes/");assertThat(html).contains("font-size:36px","font-size:16px","@media (max-width:700px)");mobile.setColor("url(javascript:1)");try(var f=jakarta.validation.Validation.buildDefaultValidatorFactory()){assertThat(f.getValidator().validate(d)).isNotEmpty();}}
    @Test void impideEtiquetasScriptsYClasesConAtributos(){var d=sencillo();var n=d.getTodosComponentes().getFirst();n.setTag("script");n.setClases("x\" onclick=\"alert(1)");try(var f=jakarta.validation.Validation.buildDefaultValidatorFactory()){assertThat(f.getValidator().validate(d)).hasSizeGreaterThanOrEqualTo(2);}}
    @Test void galeriaCarruselConservaOrdenDescripcionesYNoIncluyeFotografiasRetiradas(){var d=sencillo();var n=d.getTodosComponentes().getFirst();n.setTipo("galeria");n.setTexto("");n.setAlbumId("album-prueba");n.setPresentacion("carrusel");n.setAutomatico(true);n.setIntervalo(6);var form=form(d);var a=new SitioExtras.Album();a.setId("album-prueba");a.setTitulo("Momentos <seguros>");for(int i=0;i<3;i++){var f=new SitioExtras.Foto();f.setId("foto-"+i);f.setImagenId(10L+i);f.setDescripcion("Fotografía "+i);f.setOrden(2-i);f.setActivo(i!=1);a.getFotos().add(f);}form.getExtras().getAlbumes().add(a);String html=new SitioDisenadorRender().documento(form,"/imagenes/");assertThat(html).contains("data-nd-gallery=\"carrusel\"","data-auto=\"true\"","data-interval=\"6\"","Momentos &lt;seguros&gt;").doesNotContain("/imagenes/11");assertThat(html.indexOf("/imagenes/12")).isLessThan(html.indexOf("/imagenes/10"));n.setPresentacion("ejecutar-script");n.setIntervalo(0);try(var factory=jakarta.validation.Validation.buildDefaultValidatorFactory()){assertThat(factory.getValidator().validate(d)).hasSizeGreaterThanOrEqualTo(2);}}

    @Test void losDisenosEfectosYTransicionesSeValidanYSeConservanEnElRender(){var d=sencillo();var n=d.getTodosComponentes().getFirst();n.setTipo("galeria");n.setTexto("");n.setEfectoFoto("acercar");n.setTransicion("fundido");n.setColumnas(4);n.setMostrarDescripciones(false);var form=form(d);var a=new SitioExtras.Album();a.setId("galeria-disenos");a.setTitulo("Álbum de diseños");var foto=new SitioExtras.Foto();foto.setId("foto-segura");foto.setImagenId(10L);foto.setDescripcion("Foto <segura>");a.getFotos().add(foto);form.getExtras().getAlbumes().add(a);for(var mode:List.of("cuadricula","mosaico","muro","tarjetas","carrusel","destacada","tira")){n.setPresentacion(mode);try(var factory=jakarta.validation.Validation.buildDefaultValidatorFactory()){assertThat(factory.getValidator().validate(d)).isEmpty();}assertThat(new SitioDisenadorRender().documento(form,"/imagenes/")).contains("data-nd-gallery=\""+mode+"\"","data-effect=\"acercar\"","data-transition=\"fundido\"","--nd-gallery-columns:4","data-captions=\"false\"","data-nd-photo=\"foto-segura\"","Foto &lt;segura&gt;");}n.setEfectoFoto("javascript:1");n.setTransicion("url(otro)");n.setColumnas(30);try(var factory=jakarta.validation.Validation.buildDefaultValidatorFactory()){assertThat(factory.getValidator().validate(d)).hasSizeGreaterThanOrEqualTo(3);}}

    @Test void objetosEscolaresConservanColorGiroAccesibilidadYRecursosLocales()throws Exception {
        var d=sencillo();var n=d.getTodosComponentes().getFirst();n.setTipo("icono");n.setTexto("");n.setIcono("libro");n.setNombre("Libro");n.setDescripcion("Aprendemos leyendo <juntos>");n.setDecorativo(false);
        var style=new SitioComponente.Estilo();style.setColor("#25aaa1");style.setGiro(15);style.setAncho(150);style.setAlto(150);n.getEstilos().put("escritorio",style);
        for(var key:SitioObjetosEscolares.PATRON.split("\\|")) {n.setIcono(key);try(var f=jakarta.validation.Validation.buildDefaultValidatorFactory()){assertThat(f.getValidator().validate(d)).isEmpty();}assertThatCode(()->d.validar(true)).doesNotThrowAnyException();assertThat(new SitioDisenadorRender().documento(form(d),"/imagenes/")).contains("objetos#"+key,"nd-school-object","role=\"img\"","Aprendemos leyendo &lt;juntos&gt;","color:#25aaa1","rotate(15deg)");}
        var mapper=tools.jackson.databind.json.JsonMapper.builder().build();var copy=mapper.readValue(mapper.writeValueAsString(d),SitioDiseno.class);assertThat(copy.getTodosComponentes().getFirst().getIcono()).isEqualTo(n.getIcono());
        n.setDecorativo(true);assertThat(new SitioDisenadorRender().documento(form(d),"/imagenes/")).doesNotContain("role=\"img\"");n.setIcono("https://otro.example/icono.svg#x");try(var f=jakarta.validation.Validation.buildDefaultValidatorFactory()){assertThat(f.getValidator().validate(d)).isNotEmpty();}
        assertThat(SitioObjetosEscolares.recurso("\" onload=\"alert(1)")).endsWith("#cuaderno");n.getHijos().add(new SitioComponente());assertThatThrownBy(()->d.validar(false)).hasMessageContaining("objeto escolar");
    }
}
